import sys
import os
import json
import re
from decimal import Decimal

MONTHS = {
    'jan': 1, 'january': 1,
    'feb': 2, 'february': 2,
    'mar': 3, 'march': 3,
    'apr': 4, 'april': 4,
    'may': 5,
    'jun': 6, 'june': 6,
    'jul': 7, 'july': 7,
    'aug': 8, 'august': 8,
    'sep': 9, 'september': 9,
    'oct': 10, 'october': 10,
    'nov': 11, 'november': 11,
    'dec': 12, 'december': 12
}

def parse_date(date_str):
    cleaned = re.sub(r'(\d+)(st|nd|rd|th)', r'\1', date_str)
    cleaned = cleaned.replace(',', ' ').strip()
    parts = cleaned.split()
    if len(parts) == 3:
        p0 = parts[0].lower()
        p1 = parts[1].lower()
        if p0 in MONTHS and parts[1].isdigit():
            m = MONTHS[p0]
            d = int(parts[1])
            y = int(parts[2])
            return f"{y:04d}-{m:02d}-{d:02d}"
        elif p1 in MONTHS and parts[0].isdigit():
            d = int(parts[0])
            m = MONTHS[p1]
            y = int(parts[2])
            return f"{y:04d}-{m:02d}-{d:02d}"
    return None

def normalize_amount(raw):
    cleaned = raw.replace(',', '').replace('$', '').strip()
    if '.' in cleaned:
        return str(Decimal(cleaned))
    return str(int(cleaned))

def normalize_quantity(raw):
    cleaned = raw.replace(',', '').strip()
    return str(int(cleaned))

def split_messages(content):
    chunks = re.split(r'={20,}', content)
    messages = []
    for chunk in chunks:
        chunk = chunk.strip()
        if chunk:
            messages.append(chunk)
    return messages

def parse_records(dir_path):
    data = {
        'invoices': {},
        'purchase_orders': {},
        'receipts': {},
        'payments': {},
        'warehouse_scans': {}
    }

    # invoices
