    if os.path.exists(p):
        with open(p, 'r', encoding='utf-8') as f:
            msgs = split_messages(f.read())
        for msg in msgs:
            po_match = re.search(r'\b(PO-\d+)\b', msg)
            if not po_match:
                continue
            po = po_match.group(1)
            entry = data['invoices'].setdefault(po, {
                'invoice amount': set(),
                'quantity invoiced': set(),
                'payment due': set()
            })

            # Invoice amount
            amt_match = re.search(r'(?:bill comes to|invoice total is)\s+\$?([0-9,]+(?:\.[0-9]+)?)', msg, re.IGNORECASE)
            if amt_match:
                entry['invoice amount'].add(normalize_amount(amt_match.group(1)))

            # Quantity invoiced
            qty_match = re.search(r'(?:charged us for|lists)\s+([0-9,]+)\s+(?:units|pieces)', msg, re.IGNORECASE)
            if qty_match:
                entry['quantity invoiced'].add(normalize_quantity(qty_match.group(1)))

            # Payment due
            due_match = re.search(r'(?:settled no later than|go out by)\s+([A-Za-z0-9, ]+?)(?:\.|\n|$)', msg, re.IGNORECASE)
            if due_match:
                dt = parse_date(due_match.group(1))
                if dt:
                    entry['payment due'].add(dt)

    # purchase_orders
    p = os.path.join(dir_path, 'purchase_orders.txt')
    if os.path.exists(p):
        with open(p, 'r', encoding='utf-8') as f:
