            if not po_match:
                continue
            po = po_match.group(1)
            entry = data['purchase_orders'].setdefault(po, {
                'order amount': set()
            })

            amt_match = re.search(r'(?:value on the PO is|PO was raised for)\s+\$?([0-9,]+(?:\.[0-9]+)?)', msg, re.IGNORECASE)
            if amt_match:
                entry['order amount'].add(normalize_amount(amt_match.group(1)))

    # receipts
