    return data

def resolve_fact(data, po, primary_doc, fact_name, fallback_doc=None):
    values = data[primary_doc].get(po, {}).get(fact_name, set())
    if len(values) > 1:
        return "CONFLICT"
    if len(values) == 1:
        return [next(iter(values)), primary_doc]

    if fallback_doc:
        fb_values = data[fallback_doc].get(po, {}).get(fact_name, set())
        if len(fb_values) > 1:
            return "CONFLICT"
        if len(fb_values) == 1:
            return [next(iter(fb_values)), fallback_doc]

    return "ABSENT"

def main():
