import json
import os
import re
import sys
from datetime import date
from decimal import Decimal


def parse_date(val_str):
    val_str = val_str.strip()
    m = re.match(r"^(\d{4})-W(\d{2})-(\d)$", val_str)
    if m:
        year, week, day = int(m.group(1)), int(m.group(2)), int(m.group(3))
        return date.fromisocalendar(year, week, day).strftime("%Y-%m-%d")
    m2 = re.match(r"^\d{4}-\d{2}-\d{2}$", val_str)
    if m2:
        return val_str
    return None


def parse_amount(val_str):
    val_str = val_str.strip()
    try:
        d = Decimal(val_str)
        return str(d)
    except Exception:
        return val_str


def load_crosstab_tsv(filepath):
    if not os.path.exists(filepath):
        return []
    records = []
    with open(filepath, "r", encoding="utf-8") as f:
        lines = [line.rstrip("\r\n") for line in f if line.strip() and not line.startswith("#")]
    if not lines:
        return []

    header = lines[0].split("\t")
    num_records = len(header) - 1
    record_dicts = [{} for _ in range(num_records)]

    for line in lines[1:]:
        parts = line.split("\t")
        attr_name = parts[0].strip()
        for idx in range(num_records):
            val = parts[idx + 1].strip() if idx + 1 < len(parts) else "~"
            if val != "~" and val != "":
                record_dicts[idx][attr_name] = val

    return record_dicts


def evaluate_fact(doc_store, entity_key, primary_doc, primary_field, fallback_doc, fallback_field, val_type):
    # Retrieve values from primary document
    def get_values(doc_name, field_name):
        recs = doc_store.get(doc_name, [])
        vals = []
        for r in recs:
            if r.get("order.key") == entity_key and field_name in r:
                raw_val = r[field_name]
                if raw_val != "~" and raw_val != "":
                    if val_type == "date":
                        parsed = parse_date(raw_val)
                    else:
                        parsed = parse_amount(raw_val)
                    if parsed is not None:
                        vals.append(parsed)
        return vals

    vals = get_values(primary_doc, primary_field)
    doc_used = primary_doc

    if not vals and fallback_doc:
        vals = get_values(fallback_doc, fallback_field)
        doc_used = fallback_doc

    if not vals:
        return "ABSENT"

    # Check for conflict
    if val_type == "amount":
        try:
            first_dec = Decimal(vals[0])
            for v in vals[1:]:
                if Decimal(v) != first_dec:
                    return "CONFLICT"
        except Exception:
            if len(set(vals)) > 1:
                return "CONFLICT"
    else:
        if len(set(vals)) > 1:
            return "CONFLICT"

    return [vals[0], doc_used]


def main():
    if len(sys.argv) < 2:
        sys.exit(1)

    dir_path = sys.argv[1]

    doc_files = {
        "invoices": "invoices.tsv",
        "payments": "payments.tsv",
        "purchase_orders": "purchase_orders.tsv",
        "receipts": "receipts.tsv",
        "requisitions": "requisitions.tsv",
        "warehouse_scans": "warehouse_scans.tsv",
    }

    doc_store = {}
    all_keys = set()

    for doc_name, file_name in doc_files.items():
        records = load_crosstab_tsv(os.path.join(dir_path, file_name))
        doc_store[doc_name] = records
        for r in records:
            if "order.key" in r:
                all_keys.add(r["order.key"])

    sorted_keys = sorted(all_keys)

    rules_def = {
        "pa.three_way_match": [
            ("invoice amount", "invoices", "bill.value.usd", None, None, "amount"),
            ("order amount", "purchase_orders", "order.commit.usd", None, None, "amount"),
            ("quantity received", "receipts", "goodsin.units", None, None, "amount"),
            ("quantity invoiced", "invoices", "bill.qty.units", None, None, "amount"),
        ],
        "pa.paid_in_window": [
            ("goods received", "receipts", "goodsin.day.wk", "warehouse_scans", "scanner.hit.wk", "date"),
            ("payment date", "payments", "funds.out.wk", None, None, "date"),
            ("payment due", "invoices", "bill.deadline.wk", None, None, "date"),
        ],
    }

    results = {}

    for rule_id in ["pa.three_way_match", "pa.paid_in_window"]:
        facts_spec = rules_def[rule_id]
        for key in sorted_keys:
            pair_id = f"{rule_id}::{key}"
            pair_result = {}
            for fact_name, p_doc, p_field, fb_doc, fb_field, val_type in facts_spec:
                val = evaluate_fact(doc_store, key, p_doc, p_field, fb_doc, fb_field, val_type)
                pair_result[fact_name] = val
            results[pair_id] = pair_result

    print(json.dumps(results, indent=2))


if __name__ == "__main__":
    main()
