import sys
import os
import re
import json
import datetime
from decimal import Decimal

RULES = {
    'pa.three_way_match': [
        ('invoice amount', [('invoices', 'bill.value.usd', 'amount')]),
        ('order amount', [('purchase_orders', 'order.commit.usd', 'amount')]),
        ('quantity received', [('receipts', 'goodsin.units', 'amount')]),
        ('quantity invoiced', [('invoices', 'bill.qty.units', 'amount')]),
    ],
    'pa.paid_in_window': [
        ('goods received', [('receipts', 'goodsin.day.wk', 'date'), ('warehouse_scans', 'scanner.hit.wk', 'date')]),
        ('payment date', [('payments', 'funds.out.wk', 'date')]),
        ('payment due', [('invoices', 'bill.deadline.wk', 'date')]),
    ]
}

def parse_date(val):
    val = val.strip()
    if '-W' in val:
        parts = val.split('-W')
        year = int(parts[0])
        week, day = map(int, parts[1].split('-'))
        return datetime.date.fromisocalendar(year, week, day).strftime('%Y-%m-%d')
    return val

def parse_crosstab_tsv(file_path):
    if not os.path.exists(file_path):
        return {}
    with open(file_path, 'r', encoding='utf-8') as f:
        lines = [line.rstrip('\r\n') for line in f if line.strip() and not line.startswith('#')]

    if not lines:
        return {}

    header = lines[0].split('\t')
    num_cols = len(header) - 1

    rows = {}
    for line in lines[1:]:
        parts = line.split('\t')
        attr = parts[0].strip()
        vals = [p.strip() for p in parts[1:]]
        if len(vals) < num_cols:
            vals.extend(['~'] * (num_cols - len(vals)))
        rows[attr] = vals[:num_cols]

    records_by_key = {}
    for c in range(num_cols):
        rec = {}
        for attr, vals in rows.items():
            rec[attr] = vals[c]
        key = rec.get('order.key')
        if key and key != '~':
            records_by_key.setdefault(key, []).append(rec)

    return records_by_key

def natural_sort_key(s):
    return [int(text) if text.isdigit() else text.lower() for text in re.split(r'(\d+)', s)]

def find_all_keys(data_dir):
    keys = set()
    for fname in os.listdir(data_dir):
        if fname.endswith('.tsv'):
            fpath = os.path.join(data_dir, fname)
            try:
                with open(fpath, 'r', encoding='utf-8') as f:
                    for line in f:
                        if line.startswith('#') or not line.strip():
                            continue
                        parts = [p.strip() for p in line.split('\t')]
                        if parts and parts[0] == 'order.key':
                            for k in parts[1:]:
                                if k and k != '~':
                                    keys.add(k)
                            break
            except Exception:
                pass
    return sorted(keys, key=natural_sort_key)

def resolve_fact(entity, sources, datasets):
    for doc_name, attr_name, val_type in sources:
        doc_records = datasets.get(doc_name, {}).get(entity, [])
        raw_vals = [rec[attr_name] for rec in doc_records if attr_name in rec and rec[attr_name] not in ('~', '')]

        if not raw_vals:
            continue

        if val_type == 'date':
            parsed_vals = [parse_date(v) for v in raw_vals]
            if len(set(parsed_vals)) > 1:
                return "CONFLICT"
            return [parsed_vals[0], doc_name]
        else:
            try:
                dec_vals = [Decimal(v) for v in raw_vals]
                if len(set(dec_vals)) > 1:
                    return "CONFLICT"
                return [raw_vals[0].strip(), doc_name]
            except Exception:
                if len(set(raw_vals)) > 1:
                    return "CONFLICT"
                return [raw_vals[0].strip(), doc_name]

    return "ABSENT"

def main():
    if len(sys.argv) < 2:
        sys.exit(1)

    data_dir = sys.argv[1]

    doc_names = ['invoices', 'payments', 'purchase_orders', 'receipts', 'requisitions', 'warehouse_scans']
    datasets = {}
    for doc in doc_names:
        file_path = os.path.join(data_dir, f"{doc}.tsv")
        datasets[doc] = parse_crosstab_tsv(file_path)

    all_keys = find_all_keys(data_dir)

    result = {}
    for rule_name in ['pa.three_way_match', 'pa.paid_in_window']:
        fact_specs = RULES[rule_name]
        for key in all_keys:
            pair_id = f"{rule_name}::{key}"
            pair_facts = {}
            for fact_name, sources in fact_specs:
                pair_facts[fact_name] = resolve_fact(key, sources, datasets)
            result[pair_id] = pair_facts

    print(json.dumps(result, indent=2))

if __name__ == '__main__':
    main()
