import sys
import os
import json
from decimal import Decimal


def format_date(d_str):
    d_str = d_str.strip()
    if not d_str:
        return ""
    if "/" in d_str:
        parts = d_str.split("/")
        if len(parts) == 3:
            m, d, y = parts
            return f"{int(y):04d}-{int(m):02d}-{int(d):02d}"
    elif "-" in d_str:
        parts = d_str.split("-")
        if len(parts) == 3:
            if len(parts[0]) == 4:
                return f"{int(parts[0]):04d}-{int(parts[1]):02d}-{int(parts[2]):02d}"
            else:
                m, d, y = parts
                return f"{int(y):04d}-{int(m):02d}-{int(d):02d}"
    return d_str


def parse_file(filepath):
    records = []
    headers = None
    if not os.path.exists(filepath):
        return records
    with open(filepath, "r", encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if not line or line.startswith("#"):
                continue
            parts = [p.strip() for p in line.split("|")]
            if headers is None:
                headers = parts
            else:
                row = dict(zip(headers, parts))
                records.append(row)
    return records


def deduplicate_values(values, is_date):
    if not values:
        return []
    if is_date:
        unique = []
        for v in values:
            if v not in unique:
                unique.append(v)
        return unique
    else:
        unique = []
        for v in values:
            try:
                dec = Decimal(v)
                if not any(dec == Decimal(u) for u in unique):
                    unique.append(v)
            except Exception:
                if v not in unique:
                    unique.append(v)
        return unique


def get_fact_value(data, entity, doc_name, field_name, is_date):
    rows = data.get(doc_name, [])
    values = []
    for row in rows:
        if row.get("PURCHASE_DOCUMENT_KEY") == entity:
            val = row.get(field_name, "").strip()
            if val:
                if is_date:
                    formatted = format_date(val)
                    if formatted:
                        values.append(formatted)
                else:
                    values.append(val)
    if not values:
        return None
    unique = deduplicate_values(values, is_date)
    if len(unique) > 1:
        return "CONFLICT"
    return [unique[0], doc_name]


def resolve_fact(data, entity, primary_doc, primary_field, fallback_doc=None, fallback_field=None, is_date=False):
    res = get_fact_value(data, entity, primary_doc, primary_field, is_date)
    if res is not None:
        return res
    if fallback_doc and fallback_field:
        res_fb = get_fact_value(data, entity, fallback_doc, fallback_field, is_date)
        if res_fb is not None:
            return res_fb
    return "ABSENT"


def main():
    if len(sys.argv) < 2:
        sys.exit(1)

    dir_path = sys.argv[1]

    doc_files = {
        "invoices": "invoices.txt",
        "payments": "payments.txt",
        "purchase_orders": "purchase_orders.txt",
        "receipts": "receipts.txt",
        "requisitions": "requisitions.txt",
        "warehouse_scans": "warehouse_scans.txt",
    }

    data = {}
    po_keys = set()
    for doc_name, filename in doc_files.items():
        filepath = os.path.join(dir_path, filename)
        rows = parse_file(filepath)
        data[doc_name] = rows
        for r in rows:
            k = r.get("PURCHASE_DOCUMENT_KEY")
            if k:
                po_keys.add(k)

    sorted_pos = sorted(po_keys)

    rules = ["pa.three_way_match", "pa.paid_in_window"]
    result = {}

    for rule in rules:
        for po in sorted_pos:
            pair_id = f"{rule}::{po}"
            if rule == "pa.three_way_match":
                result[pair_id] = {
                    "invoice amount": resolve_fact(data, po, "invoices", "VENDOR_BILLED_TOTAL", is_date=False),
                    "order amount": resolve_fact(data, po, "purchase_orders", "ORDER_NET_VALUE", is_date=False),
                    "quantity received": resolve_fact(data, po, "receipts", "GR_ACCEPTED_UNITS", is_date=False),
                    "quantity invoiced": resolve_fact(data, po, "invoices", "BILLED_UNIT_COUNT", is_date=False),
                }
            elif rule == "pa.paid_in_window":
                result[pair_id] = {
                    "goods received": resolve_fact(
                        data, po, "receipts", "GR_POSTING_DAY", "warehouse_scans", "INBOUND_DOOR_EVENT_DAY", is_date=True
                    ),
                    "payment date": resolve_fact(data, po, "payments", "DISBURSEMENT_CLEARED_DAY", is_date=True),
                    "payment due": resolve_fact(data, po, "invoices", "NET_DUE_DAY", is_date=True),
                }

    print(json.dumps(result, indent=2))


if __name__ == "__main__":
    main()
