    if len(parts) == 3:
        m, d, y = parts
        return f"{int(y):04d}-{int(m):02d}-{int(d):02d}"
    return val


def read_table(filepath):
    if not os.path.exists(filepath):
        return []
    rows = []
    with open(filepath, 'r', encoding='utf-8') as f:
        header = None
        for line in f:
            line = line.rstrip('\r\n')
            if not line or line.startswith('#'):
                continue
            parts = [p.strip() for p in line.split('|')]
            if header is None:
                header = parts
            else:
                row = dict(zip(header, parts))
                rows.append(row)
    return rows


def resolve_field(docs_with_cols, po_key, value_type="string"):
    for doc_name, rows, col_name in docs_with_cols:
        vals = []
        for r in rows:
            if r.get('PURCHASE_DOCUMENT_KEY') == po_key:
                v = r.get(col_name, '').strip()
                if v:
                    if value_type == "date":
                        v = format_date(v)
                    vals.append(v)
        if not vals:
            continue
        if value_type == "decimal":
            try:
                dec_vals = [Decimal(v) for v in vals]
                if all(d == dec_vals[0] for d in dec_vals):
                    return [vals[0], doc_name]
                else:
                    return "CONFLICT"
            except Exception:
                if all(v == vals[0] for v in vals):
                    return [vals[0], doc_name]
                else:
                    return "CONFLICT"
        else:
            if all(v == vals[0] for v in vals):
                return [vals[0], doc_name]
            else:
                return "CONFLICT"
    return "ABSENT"


def main():
    if len(sys.argv) < 2:
        return

    dir_path = sys.argv[1]

    invoices_rows = read_table(os.path.join(dir_path, "invoices.txt"))
    payments_rows = read_table(os.path.join(dir_path, "payments.txt"))
    purchase_orders_rows = read_table(os.path.join(dir_path, "purchase_orders.txt"))
    receipts_rows = read_table(os.path.join(dir_path, "receipts.txt"))
    requisitions_rows = read_table(os.path.join(dir_path, "requisitions.txt"))
    warehouse_scans_rows = read_table(os.path.join(dir_path, "warehouse_scans.txt"))

    all_rows = (
        invoices_rows
        + payments_rows
        + purchase_orders_rows
        + receipts_rows
        + requisitions_rows
        + warehouse_scans_rows
    )

    po_keys = sorted(
        list(
            {
                r['PURCHASE_DOCUMENT_KEY']
                for r in all_rows
                if r.get('PURCHASE_DOCUMENT_KEY')
            }
        )
    )

    result = {}

    for po_key in po_keys:
        pair_id = f"pa.three_way_match::{po_key}"
        result[pair_id] = {
            "invoice amount": resolve_field(
                [("invoices", invoices_rows, "VENDOR_BILLED_TOTAL")],
                po_key,
                "decimal",
            ),
            "order amount": resolve_field(
                [("purchase_orders", purchase_orders_rows, "ORDER_NET_VALUE")],
                po_key,
                "decimal",
            ),
            "quantity received": resolve_field(
                [("receipts", receipts_rows, "GR_ACCEPTED_UNITS")],
                po_key,
                "decimal",
            ),
            "quantity invoiced": resolve_field(
                [("invoices", invoices_rows, "BILLED_UNIT_COUNT")],
                po_key,
                "decimal",
            ),
        }

    for po_key in po_keys:
        pair_id = f"pa.paid_in_window::{po_key}"
        result[pair_id] = {
            "goods received": resolve_field(
                [
                    ("receipts", receipts_rows, "GR_POSTING_DAY"),
                    ("warehouse_scans", warehouse_scans_rows, "INBOUND_DOOR_EVENT_DAY"),
                ],
                po_key,
                "date",
            ),
            "payment date": resolve_field(
                [("payments", payments_rows, "DISBURSEMENT_CLEARED_DAY")],
                po_key,
                "date",
            ),
            "payment due": resolve_field(
                [("invoices", invoices_rows, "NET_DUE_DAY")],
                po_key,
                "date",
            ),
        }

    print(json.dumps(result, indent=2))


if __name__ == '__main__':
    main()
