import sys
import os
import re
import json
from datetime import datetime

MONTHS = {
    'jan': '01', 'january': '01',
    'feb': '02', 'february': '02',
    'mar': '03', 'march': '03',
    'apr': '04', 'april': '04',
    'may': '05',
    'jun': '06', 'june': '06',
    'jul': '07', 'july': '07',
    'aug': '08', 'august': '08',
    'sep': '09', 'september': '09',
    'oct': '10', 'october': '10',
    'nov': '11', 'november': '11',
    'dec': '12', 'december': '12'
}

def parse_date(text):
    if not text or 'left blank' in text.lower():
        return None
    # Matches patterns like "Mon., July 13, 2026" or "July 13, 2026" or "Feb. 7, 2026"
    m = re.search(r'([A-Za-z]+)\.?\s+(\d{1,2}),\s+(\d{4})', text)
    if m:
        month_str = m.group(1).lower()
        day_str = m.group(2).zfill(2)
        year_str = m.group(3)
        month_num = MONTHS.get(month_str)
        if month_num:
            return f"{year_str}-{month_num}-{day_str}"
    return None

def parse_currency(text):
    if not text or 'left blank' in text.lower():
        return None
    # Extracts USD 109,500.00 -> 109500.00
    m = re.search(r'USD\s*([\d,]+(?:\.\d+)?)', text)
    if m:
        val = m.group(1).replace(',', '')
        if '.' not in val:
            val += '.00'
        return val
    return None

def parse_units(text):
    if not text or 'left blank' in text.lower():
        return None
    m = re.search(r'([\d,]+(?:\.\d+)?)\s*pcs', text)
    if m:
        return m.group(1).replace(',', '')
    # Fallback to pure number
    m = re.search(r'([\d,]+(?:\.\d+)?)', text)
    if m:
        return m.group(1).replace(',', '')
    return None

def parse_html_sheets(file_path):
    if not os.path.exists(file_path):
        return []
    with open(file_path, 'r', encoding='utf-8') as f:
        content = f.read()

    articles = re.findall(r'<article class="sheet".*?</article>', content, re.DOTALL)
    sheets_data = []

    for art in articles:
        # Extract rows
        rows = re.findall(r'<tr>\s*<th>(.*?)</th>\s*<td.*?>(.*?)</td>\s*</tr>', art, re.DOTALL)
        row_dict = {}
        for th, td in rows:
            # Strip tags
            th_clean = re.sub(r'<.*?>', '', th).strip()
            # If td contains class="void", treat as empty
            if 'class="void"' in td or 'left blank' in td.lower():
                val = None
            else:
                val = re.sub(r'<.*?>', '', td).strip()
            row_dict[th_clean] = val
        sheets_data.append(row_dict)

    return sheets_data

def build_fact(doc_values, doc_name):
    """
    doc_values is a list of valid values extracted from doc_name for a given PO.
    Returns: ["<value>", "<doc_name>"], "ABSENT", or "CONFLICT"
    """
    if not doc_values:
        return "ABSENT"
    unique_vals = list(dict.fromkeys(doc_values))
    if len(unique_vals) == 1:
        return [unique_vals[0], doc_name]
    else:
        return "CONFLICT"

def main():
    if len(sys.argv) < 2:
        print("{}")
        return

    data_dir = sys.argv[1]

    invoices_file = os.path.join(data_dir, "invoices.html")
    payments_file = os.path.join(data_dir, "payments.html")
    po_file = os.path.join(data_dir, "purchase_orders.html")
    receipts_file = os.path.join(data_dir, "receipts.html")
    scans_file = os.path.join(data_dir, "warehouse_scans.html")

    invoices_sheets = parse_html_sheets(invoices_file)
    payments_sheets = parse_html_sheets(payments_file)
    po_sheets = parse_html_sheets(po_file)
    receipts_sheets = parse_html_sheets(receipts_file)
    scans_sheets = parse_html_sheets(scans_file)

    # Collect data by PO
    # Invoices: invoice amount, quantity invoiced, payment due
    invoices_by_po = {}
    for s in invoices_sheets:
        po = s.get('Procurement reference')
        if not po:
            continue
        invoices_by_po.setdefault(po, []).append(s)

    po_by_po = {}
    for s in po_sheets:
        po = s.get('Procurement reference')
        if not po:
            continue
        po_by_po.setdefault(po, []).append(s)

    receipts_by_po = {}
    for s in receipts_sheets:
        po = s.get('Procurement reference')
        if not po:
            continue
        receipts_by_po.setdefault(po, []).append(s)

    scans_by_po = {}
    for s in scans_sheets:
        po = s.get('Procurement reference')
        if not po:
            continue
        scans_by_po.setdefault(po, []).append(s)

    payments_by_po = {}
    for s in payments_sheets:
        po = s.get('Procurement reference')
        if not po:
            continue
        payments_by_po.setdefault(po, []).append(s)

    # Pairs defined
    all_po_nums = [f"PO-{i}" for i in range(40301, 40317)]
    result = {}

    for po in all_po_nums:
        # Rule: pa.three_way_match
        pair_id_twm = f"pa.three_way_match::{po}"

        # invoice amount from invoices
        inv_amt_vals = []
        for s in invoices_by_po.get(po, []):
            raw = s.get('Invoice grand total')
            v = parse_currency(raw)
            if v is not None:
                inv_amt_vals.append(v)
        fact_inv_amt = build_fact(inv_amt_vals, "invoices")

        # order amount from purchase_orders
        ord_amt_vals = []
        for s in po_by_po.get(po, []):
            raw = s.get('Total order value')
            v = parse_currency(raw)
            if v is not None:
                ord_amt_vals.append(v)
        fact_ord_amt = build_fact(ord_amt_vals, "purchase_orders")

        # quantity received from receipts
        qty_rcv_vals = []
        for s in receipts_by_po.get(po, []):
            raw = s.get('Units counted on delivery')
            v = parse_units(raw)
            if v is not None:
                qty_rcv_vals.append(v)
        fact_qty_rcv = build_fact(qty_rcv_vals, "receipts")

        # quantity invoiced from invoices
        qty_inv_vals = []
        for s in invoices_by_po.get(po, []):
            raw = s.get('Units charged')
            v = parse_units(raw)
            if v is not None:
                qty_inv_vals.append(v)
        fact_qty_inv = build_fact(qty_inv_vals, "invoices")

        result[pair_id_twm] = {
            "invoice amount": fact_inv_amt,
            "order amount": fact_ord_amt,
            "quantity received": fact_qty_rcv,
            "quantity invoiced": fact_qty_inv
        }

        # Rule: pa.paid_in_window
        pair_id_piw = f"pa.paid_in_window::{po}"

        # goods received: receipts; fallback warehouse_scans
        gr_vals_rcpt = []
        for s in receipts_by_po.get(po, []):
            raw = s.get('Delivery booked')
            v = parse_date(raw)
            if v is not None:
                gr_vals_rcpt.append(v)

        if gr_vals_rcpt:
            fact_gr = build_fact(gr_vals_rcpt, "receipts")
        else:
            # fallback
            gr_vals_scan = []
            for s in scans_by_po.get(po, []):
                raw = s.get('Dock scanner stamp')
                v = parse_date(raw)
                if v is not None:
                    gr_vals_scan.append(v)
            fact_gr = build_fact(gr_vals_scan, "warehouse_scans")

        # payment date from payments
        pmt_date_vals = []
        for s in payments_by_po.get(po, []):
            raw = s.get('Funds released')
            v = parse_date(raw)
            if v is not None:
                pmt_date_vals.append(v)
        fact_pmt_date = build_fact(pmt_date_vals, "payments")

        # payment due from invoices
        pmt_due_vals = []
        for s in invoices_by_po.get(po, []):
            raw = s.get('Payment deadline')
            v = parse_date(raw)
            if v is not None:
                pmt_due_vals.append(v)
        fact_pmt_due = build_fact(pmt_due_vals, "invoices")

        result[pair_id_piw] = {
            "goods received": fact_gr,
            "payment date": fact_pmt_date,
            "payment due": fact_pmt_due
        }

    print(json.dumps(result, indent=2))

if __name__ == '__main__':
    main()
