import sys
import os
import re
import json
from html.parser import HTMLParser

MONTHS = {
    'jan': 1, 'january': 1,
    'feb': 2, 'february': 2,
    'mar': 3, 'march': 3,
    'apr': 4, 'april': 4,
    'may': 5,
    'jun': 6, 'june': 6,
    'jul': 7, 'july': 7,
    'aug': 8, 'august': 8,
    'sep': 9, 'sept': 9, 'september': 9,
    'oct': 10, 'october': 10,
    'nov': 11, 'november': 11,
    'dec': 12, 'december': 12,
}

def parse_date(val_str):
    val_str = val_str.strip()
    m_iso = re.search(r'\b(\d{4})-(\d{2})-(\d{2})\b', val_str)
    if m_iso:
        return f"{int(m_iso.group(1)):04d}-{int(m_iso.group(2)):02d}-{int(m_iso.group(3)):02d}"
    m = re.search(r'(?:[A-Za-z]+[.,]?\s+)?([A-Za-z]+)\.?\s+(\d{1,2}),?\s+(\d{4})', val_str)
    if m:
        mon_str = m.group(1).lower().rstrip('.')
        if mon_str in MONTHS:
            month = MONTHS[mon_str]
            day = int(m.group(2))
            year = int(m.group(3))
            return f"{year:04d}-{month:02d}-{day:02d}"
    return None

def parse_amount(val_str):
    val_str = val_str.strip()
    m = re.search(r'([\d,]+(?:\.\d+)?)', val_str)
    if m:
        num_str = m.group(1).replace(',', '')
        return num_str
    return None

class TableExtractor(HTMLParser):
    def __init__(self):
        super().__init__()
        self.sheets = []
        self.current_sheet = None
        self.in_sheet = False
        self.in_th = False
        self.in_td = False
        self.current_th = ""
        self.current_td = ""
        self.td_is_void = False

    def handle_starttag(self, tag, attrs):
        attrs_dict = dict(attrs)
        if tag == 'article' and 'sheet' in attrs_dict.get('class', '').split():
            self.in_sheet = True
            self.current_sheet = {}
        elif self.in_sheet:
            if tag == 'th':
                self.in_th = True
                self.current_th = ""
            elif tag == 'td':
                self.in_td = True
                self.current_td = ""
                classes = attrs_dict.get('class', '').split()
                self.td_is_void = 'void' in classes

    def handle_endtag(self, tag):
        if tag == 'article' and self.in_sheet:
            self.in_sheet = False
            if self.current_sheet:
                self.sheets.append(self.current_sheet)
            self.current_sheet = None
        elif self.in_sheet:
            if tag == 'th':
                self.in_th = False
            elif tag == 'td':
                self.in_td = False
                key = self.current_th.strip()
                val = self.current_td.strip()
                if self.td_is_void or 'left blank' in val.lower():
                    val = None
                if key:
                    self.current_sheet[key] = val

    def handle_data(self, data):
        if self.in_th:
            self.current_th += data
        elif self.in_td:
            self.current_td += data

def parse_html_file(file_path):
    if not os.path.exists(file_path):
        return []
    with open(file_path, 'r', encoding='utf-8') as f:
        content = f.read()
    parser = TableExtractor()
    parser.feed(content)
    return parser.sheets

def extract_file_records(dir_path, filename):
    for ext in ['.html', '.htm', '']:
        path = os.path.join(dir_path, filename + ext)
        if os.path.exists(path):
            return parse_html_file(path)
    return []

def main():
    if len(sys.argv) < 2:
        return
    dir_path = sys.argv[1]

    invoices_sheets = extract_file_records(dir_path, 'invoices')
    po_sheets = extract_file_records(dir_path, 'purchase_orders')
    receipts_sheets = extract_file_records(dir_path, 'receipts')
    payments_sheets = extract_file_records(dir_path, 'payments')
    scans_sheets = extract_file_records(dir_path, 'warehouse_scans')

    doc_data = {
        'invoices': invoices_sheets,
        'purchase_orders': po_sheets,
        'receipts': receipts_sheets,
        'payments': payments_sheets,
        'warehouse_scans': scans_sheets,
    }

    pairs_to_evaluate = [
        ("pa.three_way_match", f"PO-{i}") for i in range(40401, 40417)
    ] + [
        ("pa.paid_in_window", f"PO-{i}") for i in range(40401, 40417)
    ]

    def get_values_from_doc(doc_name, entity_id, field_name, val_type):
        sheets = doc_data.get(doc_name, [])
        vals = []
        for s in sheets:
            ref = s.get('Procurement reference')
            if ref and ref.strip() == entity_id:
                raw_val = s.get(field_name)
                if raw_val is not None:
                    parsed = parse_amount(raw_val) if val_type == 'amount' else parse_date(raw_val)
                    if parsed is not None:
                        vals.append(parsed)
        return vals

    def resolve_field(entity_id, primary_doc, primary_field, val_type, fallback_doc=None, fallback_field=None):
        vals = get_values_from_doc(primary_doc, entity_id, primary_field, val_type)
        if vals:
            unique_vals = set(vals)
            if len(unique_vals) == 1:
                return [vals[0], primary_doc]
            else:
                return "CONFLICT"
        if fallback_doc and fallback_field:
            fb_vals = get_values_from_doc(fallback_doc, entity_id, fallback_field, val_type)
            if fb_vals:
                unique_fb = set(fb_vals)
                if len(unique_fb) == 1:
                    return [fb_vals[0], fallback_doc]
                else:
                    return "CONFLICT"
        return "ABSENT"

    output = {}

    for rule_name, po_id in pairs_to_evaluate:
        pair_key = f"{rule_name}::{po_id}"
        if rule_name == "pa.three_way_match":
            facts = {
                "invoice amount": resolve_field(po_id, 'invoices', 'Invoice grand total', 'amount'),
                "order amount": resolve_field(po_id, 'purchase_orders', 'Total order value', 'amount'),
                "quantity received": resolve_field(po_id, 'receipts', 'Units counted on delivery', 'amount'),
                "quantity invoiced": resolve_field(po_id, 'invoices', 'Units charged', 'amount'),
            }
            output[pair_key] = facts
        elif rule_name == "pa.paid_in_window":
            facts = {
                "goods received": resolve_field(po_id, 'receipts', 'Delivery booked', 'date',
                                                fallback_doc='warehouse_scans', fallback_field='Dock scanner stamp'),
                "payment date": resolve_field(po_id, 'payments', 'Funds released', 'date'),
                "payment due": resolve_field(po_id, 'invoices', 'Payment deadline', 'date'),
            }
            output[pair_key] = facts

    print(json.dumps(output, indent=2))

if __name__ == '__main__':
    main()
