import sys
import os
import sqlite3
import json
from decimal import Decimal
from datetime import date, timedelta


def format_epd(epd_val):
    d = date(1970, 1, 1) + timedelta(days=int(epd_val))
    return d.isoformat()


def format_usd(cents_val):
    d = Decimal(str(cents_val)) / Decimal(100)
    if d == d.to_integral():
        return str(d.to_integral())
    return f"{d:f}".rstrip('0').rstrip('.')


def format_units(ct_val):
    d = Decimal(str(ct_val))
    if d == d.to_integral():
        return str(d.to_integral())
    return f"{d:f}".rstrip('0').rstrip('.')


def main():
    if len(sys.argv) < 2:
        sys.exit(1)
    dir_path = sys.argv[1]

    doc_files = [
        ("invoices", "invoices.sql"),
        ("purchase_orders", "purchase_orders.sql"),
        ("receipts", "receipts.sql"),
        ("warehouse_scans", "warehouse_scans.sql"),
        ("payments", "payments.sql"),
    ]

    doc_data = {}
    all_codes = set()

    for doc_name, filename in doc_files:
        file_path = os.path.join(dir_path, filename)
        doc_data[doc_name] = {}
        if not os.path.exists(file_path):
            continue

        conn = sqlite3.connect(":memory:")
        with open(file_path, "r", encoding="utf-8") as f:
            conn.executescript(f.read())

        cursor = conn.cursor()
        cursor.execute("SELECT name FROM sqlite_master WHERE type='table'")
        tables = [row[0] for row in cursor.fetchall()]

        for tbl in tables:
            cursor.execute(f"SELECT * FROM {tbl}")
            cols = [desc[0] for desc in cursor.description]
            for row in cursor.fetchall():
                row_dict = dict(zip(cols, row))
                code = row_dict.get("ord_code")
                if code is not None:
                    doc_data[doc_name].setdefault(code, []).append(row_dict)
                    all_codes.add(code)
        conn.close()

    sorted_codes = sorted(all_codes)

    def resolve_fact(entity_code, primary_doc, primary_col, primary_formatter,
                     fallback_doc=None, fallback_col=None, fallback_formatter=None):
        rows = doc_data.get(primary_doc, {}).get(entity_code, [])
        vals = [r[primary_col] for r in rows if r.get(primary_col) is not None]
        if vals:
            formatted = [primary_formatter(v) for v in vals]
            if len(set(formatted)) > 1:
                return "CONFLICT"
            return [formatted[0], primary_doc]

        if fallback_doc:
            fb_rows = doc_data.get(fallback_doc, {}).get(entity_code, [])
            fb_vals = [r[fallback_col] for r in fb_rows if r.get(fallback_col) is not None]
            if fb_vals:
                formatted = [fallback_formatter(v) for v in fb_vals]
                if len(set(formatted)) > 1:
                    return "CONFLICT"
                return [formatted[0], fallback_doc]

        return "ABSENT"

    out = {}

    for code in sorted_codes:
        pair_id = f"pa.three_way_match::{code}"
        out[pair_id] = {
            "invoice amount": resolve_fact(code, "invoices", "billed_cents", format_usd),
            "order amount": resolve_fact(code, "purchase_orders", "commit_cents", format_usd),
            "quantity received": resolve_fact(code, "receipts", "dock_unit_ct", format_units),
            "quantity invoiced": resolve_fact(code, "invoices", "billed_unit_ct", format_units),
        }

    for code in sorted_codes:
        pair_id = f"pa.paid_in_window::{code}"
        out[pair_id] = {
            "goods received": resolve_fact(code, "receipts", "goods_in_epd", format_epd,
                                           "warehouse_scans", "scanner_hit_epd", format_epd),
            "payment date": resolve_fact(code, "payments", "funds_out_epd", format_epd),
