import sys
import os
import json
import sqlite3
from datetime import date, timedelta
from decimal import Decimal

RULES = {
    "pa.three_way_match": [
        ("invoice amount", "invoices", "cents", "USD", None, None),
        ("order amount", "purchase_orders", "cents", "USD", None, None),
        ("quantity received", "receipts", "ct", "units", None, None),
        ("quantity invoiced", "invoices", "ct", "units", None, None),
    ],
    "pa.paid_in_window": [
        ("goods received", "receipts", "epd", "date", "warehouse_scans", "epd"),
        ("payment date", "payments", "epd", "date", None, None),
        ("payment due", "invoices", "epd", "date", None, None),
    ]
}


def load_databases(dir_path):
    docs = {}
    doc_names = ["invoices", "payments", "purchase_orders", "receipts", "requisitions", "warehouse_scans"]
    for doc in doc_names:
        file_path = os.path.join(dir_path, f"{doc}.sql")
        if os.path.isfile(file_path):
            con = sqlite3.connect(":memory:")
            with open(file_path, "r", encoding="utf-8") as f:
                con.executescript(f.read())
            docs[doc] = con
    return docs


def find_column(con, table_name, col_type):
    cur = con.cursor()
    cur.execute(f"PRAGMA table_info({table_name})")
    cols = [row[1] for row in cur.fetchall()]
    for c in cols:
        if col_type in c.lower():
            return c
    return None


def get_table_name(con):
    cur = con.cursor()
    cur.execute("SELECT name FROM sqlite_master WHERE type='table'")
    tables = cur.fetchall()
    return tables[0][0] if tables else None


def format_value(val, unit):
    if unit == "USD":
        d = Decimal(str(val)) / Decimal("100")
        return str(d)
    elif unit == "units":
        if isinstance(val, float) and val.is_integer():
            val = int(val)
        return str(val)
    elif unit == "date":
        d = date(1970, 1, 1) + timedelta(days=int(val))
        return d.isoformat()
    return str(val)


def extract_fact_from_doc(con, doc_name, ord_code, col_type, unit):
    if con is None:
        return None
    tbl = get_table_name(con)
    if not tbl:
        return None
    col = find_column(con, tbl, col_type)
    if not col:
        return None
    cur = con.cursor()
    cur.execute(f"SELECT {col} FROM {tbl} WHERE ord_code = ?", (ord_code,))
    rows = cur.fetchall()
    non_null_vals = [r[0] for r in rows if r[0] is not None]
    if not non_null_vals:
        return None
    unique_vals = set(non_null_vals)
    if len(unique_vals) > 1:
        return "CONFLICT"
    return [format_value(non_null_vals[0], unit), doc_name]


def evaluate_fact(docs, ord_code, primary_doc, primary_col, unit, fallback_doc, fallback_col):
    res = extract_fact_from_doc(docs.get(primary_doc), primary_doc, ord_code, primary_col, unit)
    if res is not None:
        return res
    if fallback_doc:
        res_fb = extract_fact_from_doc(docs.get(fallback_doc), fallback_doc, ord_code, fallback_col, unit)
        if res_fb is not None:
            return res_fb
    return "ABSENT"


def get_pairs(dir_path, docs):
    for fname in os.listdir(dir_path):
        if "pair" in fname.lower():
            p_path = os.path.join(dir_path, fname)
            if os.path.isfile(p_path):
                try:
                    with open(p_path, "r", encoding="utf-8") as f:
                        content = f.read().strip()
                    data = json.loads(content)
                    if isinstance(data, list):
                        return data
                    elif isinstance(data, dict):
                        return list(data.keys())
                except Exception:
                    lines = [line.strip() for line in content.splitlines() if line.strip() and "::" in line]
                    if lines:
                        return lines

    ord_codes = set()
    for con in docs.values():
        tbl = get_table_name(con)
        if tbl:
            cur = con.cursor()
            try:
                cur.execute(f"SELECT DISTINCT ord_code FROM {tbl}")
                for (code,) in cur.fetchall():
                    if code:
                        ord_codes.add(code)
            except Exception:
                pass
    sorted_codes = sorted(ord_codes)
    pairs = []
    for rule in ["pa.three_way_match", "pa.paid_in_window"]:
        for code in sorted_codes:
            pairs.append(f"{rule}::{code}")
    return pairs


def main():
    if len(sys.argv) < 2:
        return
    dir_path = sys.argv[1]
    docs = load_databases(dir_path)
    pairs = get_pairs(dir_path, docs)

    output = {}
    for pair in pairs:
        if "::" not in pair:
            continue
        rule_name, ord_code = pair.split("::", 1)
        facts_spec = RULES.get(rule_name, [])
        pair_result = {}
        for fact_name, p_doc, p_col, unit, fb_doc, fb_col in facts_spec:
            pair_result[fact_name] = evaluate_fact(docs, ord_code, p_doc, p_col, unit, fb_doc, fb_col)
        output[pair] = pair_result

    print(json.dumps(output, indent=2))


if __name__ == "__main__":
    main()
