import sys
import os
import json
from decimal import Decimal
from collections import defaultdict

def parse_edi_segments(filepath):
    if not os.path.exists(filepath):
        return []
    with open(filepath, 'r', encoding='utf-8') as f:
        content = f.read()
    raw_segments = content.split('~')
    segments = []
    for s in raw_segments:
        s = s.strip()
        if not s:
            continue
        elements = s.split('*')
        segments.append(elements)
    return segments

def extract_loops(segments):
    loops = []
    current_loop = None
    for seg in segments:
        if seg[0] == 'LX':
            if current_loop is not None:
                loops.append(current_loop)
            current_loop = []
        elif current_loop is not None:
            if seg[0] in ('CTT', 'SE', 'GE', 'IEA'):
                loops.append(current_loop)
                current_loop = None
            else:
                current_loop.append(seg)
    if current_loop is not None:
        loops.append(current_loop)
    return loops

def parse_date(raw):
    raw = raw.strip()
    return f"{raw[:4]}-{raw[4:6]}-{raw[6:8]}"

def main():
    if len(sys.argv) < 2:
        sys.exit(1)
    dir_path = sys.argv[1]

    doc_files = {
        "invoices": "invoices.edi",
        "payments": "payments.edi",
        "purchase_orders": "purchase_orders.edi",
        "receipts": "receipts.edi",
        "requisitions": "requisitions.edi",
        "warehouse_scans": "warehouse_scans.edi",
    }

    # Store extracted facts: doc_facts[doc_name][po][fact_name] = list of values
    doc_facts = {doc: defaultdict(lambda: defaultdict(list)) for doc in doc_files}
    all_pos = set()

    # Process each document
    for doc_name, filename in doc_files.items():
        filepath = os.path.join(dir_path, filename)
        segments = parse_edi_segments(filepath)
        loops = extract_loops(segments)

        for loop in loops:
            po = None
            for seg in loop:
                if seg[0] == 'REF' and len(seg) > 2 and seg[1] == 'PO':
                    po = seg[2].strip()
                    break
            if not po:
                continue

            all_pos.add(po)

            for seg in loop:
                tag = seg[0]
                if doc_name == "invoices":
                    if tag == 'TDS' and len(seg) > 1:
                        raw = seg[1].strip()
                        if '.' in raw:
                            val = f"{Decimal(raw):.2f}"
                        else:
                            val = f"{Decimal(raw) / Decimal(100):.2f}"
                        doc_facts[doc_name][po]['invoice amount'].append(val)
                    elif tag == 'QTY' and len(seg) > 2 and seg[1] == 'D1':
                        val = str(Decimal(seg[2].strip()))
                        doc_facts[doc_name][po]['quantity invoiced'].append(val)
                    elif tag == 'DTP' and len(seg) > 3 and seg[1] == '481' and seg[2] == 'D8':
                        val = parse_date(seg[3])
                        doc_facts[doc_name][po]['payment due'].append(val)

                elif doc_name == "purchase_orders":
                    if tag == 'AMT' and len(seg) > 2 and seg[1] == 'TT':
                        val = f"{Decimal(seg[2].strip()):.2f}"
                        doc_facts[doc_name][po]['order amount'].append(val)

                elif doc_name == "receipts":
                    if tag == 'QTY' and len(seg) > 2 and seg[1] == 'RC':
                        val = str(Decimal(seg[2].strip()))
                        doc_facts[doc_name][po]['quantity received'].append(val)
                    elif tag == 'DTP' and len(seg) > 3 and seg[1] == '050' and seg[2] == 'D8':
                        val = parse_date(seg[3])
                        doc_facts[doc_name][po]['goods received'].append(val)

                elif doc_name == "warehouse_scans":
                    if tag == 'DTP' and len(seg) > 3 and seg[1] == '945' and seg[2] == 'D8':
                        val = parse_date(seg[3])
                        doc_facts[doc_name][po]['goods received'].append(val)

                elif doc_name == "payments":
                    if tag == 'DTP' and len(seg) > 3 and seg[1] == '234' and seg[2] == 'D8':
                        val = parse_date(seg[3])
                        doc_facts[doc_name][po]['payment date'].append(val)

    def resolve_in_doc(doc_name, po, fact_name):
        vals = doc_facts[doc_name][po].get(fact_name, [])
        if not vals:
            return None
        unique_vals = list(set(vals))
        if len(unique_vals) == 1:
            return unique_vals[0]
        return "CONFLICT"

    def get_fact_value(po, fact_name, primary_doc, fallback_doc=None):
        res1 = resolve_in_doc(primary_doc, po, fact_name)
        if res1 == "CONFLICT":
            return "CONFLICT"
        if res1 is not None:
            return [res1, primary_doc]
        if fallback_doc:
            res2 = resolve_in_doc(fallback_doc, po, fact_name)
            if res2 == "CONFLICT":
                return "CONFLICT"
            if res2 is not None:
                return [res2, fallback_doc]
        return "ABSENT"

    rules_definition = [
        ("pa.three_way_match", [
            ("invoice amount", "invoices", None),
            ("order amount", "purchase_orders", None),
            ("quantity received", "receipts", None),
            ("quantity invoiced", "invoices", None),
        ]),
        ("pa.paid_in_window", [
            ("goods received", "receipts", "warehouse_scans"),
            ("payment date", "payments", None),
            ("payment due", "invoices", None),
        ])
    ]

    output = {}
    sorted_pos = sorted(all_pos)

    for rule_name, facts in rules_definition:
        for po in sorted_pos:
            pair_id = f"{rule_name}::{po}"
            pair_obj = {}
            for fact_name, primary_doc, fallback_doc in facts:
                pair_obj[fact_name] = get_fact_value(po, fact_name, primary_doc, fallback_doc)
            output[pair_id] = pair_obj

    print(json.dumps(output, indent=2))

if __name__ == '__main__':
    main()
