import sys
import os
import json
from decimal import Decimal
from collections import defaultdict


def read_file(dir_path, name):
    for fname in [f"{name}.edi", name, f"{name}.txt"]:
        p = os.path.join(dir_path, fname)
        if os.path.exists(p):
            with open(p, "r", encoding="utf-8") as f:
                return f.read()
    return None


def parse_edi_loops(content):
    if not content:
        return []
    segments = [s.strip() for s in content.split("~") if s.strip()]
    loops = []
    current_loop = None
    for seg in segments:
        parts = [p.strip() for p in seg.split("*")]
        tag = parts[0]
        if tag == "LX":
            if current_loop is not None:
                loops.append(current_loop)
            current_loop = []
        elif tag in ("CTT", "SE", "GE", "IEA"):
            if current_loop is not None:
                loops.append(current_loop)
                current_loop = None
        else:
            if current_loop is not None:
                current_loop.append(parts)
    if current_loop is not None:
        loops.append(current_loop)
    return loops


def get_po_id(loop):
    for parts in loop:
        if len(parts) >= 3 and parts[0] == "REF" and parts[1] == "PO":
            return parts[2]
    return None


def format_date(d_str):
    d_str = d_str.strip()
    if len(d_str) == 8 and d_str.isdigit():
        return f"{d_str[:4]}-{d_str[4:6]}-{d_str[6:8]}"
    return d_str


def format_tds(val_str):
    val_str = val_str.strip()
    if "." in val_str:
        d = Decimal(val_str)
    else:
        d = Decimal(val_str) / Decimal(100)
    return f"{d:.2f}"


def format_amt(val_str):
    val_str = val_str.strip()
    d = Decimal(val_str)
    return f"{d:.2f}"


def format_qty(val_str):
    val_str = val_str.strip()
    d = Decimal(val_str)
    if d == int(d):
        return str(int(d))
    return str(d)


def resolve_fact(entity, fact_name, doc_name, doc_data, fallback_doc_name=None, fallback_doc_data=None):
    values = doc_data.get(entity, {}).get(fact_name, [])
    if values:
        unique_values = list(set(values))
        if len(unique_values) == 1:
            return [unique_values[0], doc_name]
        return "CONFLICT"

    if fallback_doc_name and fallback_doc_data is not None:
        fallback_values = fallback_doc_data.get(entity, {}).get(fact_name, [])
        if fallback_values:
            unique_fb = list(set(fallback_values))
            if len(unique_fb) == 1:
                return [unique_fb[0], fallback_doc_name]
            return "CONFLICT"

    return "ABSENT"


def main():
    if len(sys.argv) < 2:
        sys.exit(1)
    dir_path = sys.argv[1]

    # Data structures to hold extracted facts: doc_data[po_id][fact_name] = [values...]
    invoices_data = defaultdict(lambda: defaultdict(list))
    purchase_orders_data = defaultdict(lambda: defaultdict(list))
    receipts_data = defaultdict(lambda: defaultdict(list))
    warehouse_scans_data = defaultdict(lambda: defaultdict(list))
    payments_data = defaultdict(lambda: defaultdict(list))

    all_pos = set()

    # Parse invoices
    content = read_file(dir_path, "invoices")
    if content:
        for loop in parse_edi_loops(content):
            po_id = get_po_id(loop)
            if not po_id:
                continue
            all_pos.add(po_id)
            for parts in loop:
                if parts[0] == "TDS" and len(parts) >= 2 and parts[1]:
                    invoices_data[po_id]["invoice amount"].append(format_tds(parts[1]))
                elif parts[0] == "QTY" and len(parts) >= 3 and parts[1] == "D1" and parts[2]:
                    invoices_data[po_id]["quantity invoiced"].append(format_qty(parts[2]))
                elif parts[0] == "DTP" and len(parts) >= 4 and parts[1] == "481" and parts[3]:
                    invoices_data[po_id]["payment due"].append(format_date(parts[3]))

    # Parse purchase_orders
