    if content:
        for loop in parse_edi_loops(content):
            po_id = get_po_id(loop)
            if not po_id:
                continue
            all_pos.add(po_id)
            for parts in loop:
                if parts[0] == "AMT" and len(parts) >= 3 and parts[1] == "TT" and parts[2]:
                    purchase_orders_data[po_id]["order amount"].append(format_amt(parts[2]))

    # Parse receipts
    content = read_file(dir_path, "receipts")
    if content:
        for loop in parse_edi_loops(content):
            po_id = get_po_id(loop)
            if not po_id:
