            all_pos.add(po_id)
            for parts in loop:
                if parts[0] == "QTY" and len(parts) >= 3 and parts[1] == "RC" and parts[2]:
                    receipts_data[po_id]["quantity received"].append(format_qty(parts[2]))
                elif parts[0] == "DTP" and len(parts) >= 4 and parts[1] == "050" and parts[3]:
                    receipts_data[po_id]["goods received"].append(format_date(parts[3]))

    # Parse warehouse_scans
    content = read_file(dir_path, "warehouse_scans")
