                    warehouse_scans_data[po_id]["goods received"].append(format_date(parts[3]))

    # Parse payments
    content = read_file(dir_path, "payments")
    if content:
        for loop in parse_edi_loops(content):
            po_id = get_po_id(loop)
            if not po_id:
                continue
