```python
import sys
import os
import re
import json

MONTHS = {
    'jan': 1, 'january': 1,
    'feb': 2, 'february': 2,
    'mar': 3, 'march': 3,
    'apr': 4, 'april': 4,
    'may': 5,
    'jun': 6, 'june': 6,
    'jul': 7, 'july': 7,
    'aug': 8, 'august': 8,
    'sep': 9, 'september': 9,
    'oct': 10, 'october': 10,
    'nov': 11, 'november': 11,
    'dec': 12, 'december': 12
}

def parse_date(text):
    if not text:
        return None
    cleaned = re.sub(r'(\d+)(st|nd|rd|th)', r'\1', text)
    m1 = re.search(r'([A-Za-z]+)\s+(\d{1,2}),?\s+(\d{4})', cleaned)
    if m1:
        mon = m1.group(1).lower()
        if mon in MONTHS:
            return f"{int(m1.group(3)):04d}-{MONTHS[mon]:02d}-{int(m1.group(2)):02d}"
    m2 = re.search(r'(\d{1,2})\s+([A-Za-z]+)\s+(\d{4})', cleaned)
    if m2:
        mon = m2.group(2).lower()
        if mon in MONTHS:
            return f"{int(m2.group(3)):04d}-{MONTHS[mon]:02d}-{int(m2.group(1)):02d}"
    m3 = re.search(r'(\d{4})-(\d{2})-(\d{2})', cleaned)
    if m3:
        return f"{m3.group(1)}-{m3.group(2)}-{m3.group(3)}"
    return None

def normalize_amount(s):
    if not s:
        return None
    s = s.replace('$', '').replace(',', '').strip()
    try:
        val = float(s)
        if val.is_integer():
            return str(int(val))
        return str(val)
    except ValueError:
        return None

def load_messages(file_path):
    if not os.path.exists(file_path):
        return []
    with open(file_path, 'r', encoding='utf-8') as f:
        content = f.read()
    chunks = re.split(r'={10,}', content)
    messages = []
    for chunk in chunks:
        po_match = re.search(r'\bPO-\d+\b', chunk)
        if po_match:
            messages.append((po_match.group(0), chunk))
    return messages

def extract_invoice_amount(body):
    if re.search(r"bill total isn't on the copy|not on the copy|no invoice total", body, re.I):
        return None
    m = re.search(r"(?:invoice total is|vendor's bill comes to|bill comes to|invoice amount is)\s+\$?([0-9,]+(?:\.[0-9]+)?)", body, re.I)
    if m:
        return normalize_amount(m.group(1))
    return None

def extract_invoice_quantity(body):
    m = re.search(r"(?:charged us for|bill lists|billed for)\s+([0-9,]+)\s+(?:units|pieces)", body, re.I)
    if m:
        return normalize_amount(m.group(1))
    return None

def extract_payment_due(body):
    if re.search(r"no payment deadline", body, re.I):
        return None
    m = re.search(r"(?:payment has to go out by|bill must be settled no later than|payment due by|due date is)\s+([^.\n]+)", body, re.I)
    if m:
        return parse_date(m.group(1))
    return None

def extract_po_amount(body):
    m = re.search(r"(?:PO was raised for|committed value on the PO is|PO total is|committed value is)\s+\$?([0-9,]+(?:\.[0-9]+)?)", body, re.I)
    if m:
        return normalize_amount(m.group(1))
    return None

def extract_receipt_quantity(body):
    if re.search(r"no count was taken", body, re.I):
        return None
    m = re.search(r"(?:receiving tallied|we counted|counted)\s+([0-9,]+)\s+(?:units|pieces)", body, re.I)
    if m:
        return normalize_amount(m.group(1))
    return None

def extract_receipt_date(body):
    if re.search(r"don't have a booking-in day|no booking-in date|no booking-in day", body, re.I):
        return None
    m = re.search(r"(?:booked in on|logged as received on|received on)\s+([^.\n]+)", body, re.I)
    if m:
        return parse_date(m.group(1))
    return None

def extract_warehouse_scan_date(body):
    m = re.search(r"(?:scanner stamp at the dock reads|dock scanner picked it up on|scanned on)\s+([^.\n]+)", body, re.I)
    if m:
        return parse_date(m.group(1))
    return None

def extract_payment_date(body):
    m = re.search(r"(?:funds were released to the vendor on|we sent the money on|paid on)\s+([^.\n]+)", body, re.I)
    if m:
        return parse_date(m.group(1))
    return None

def main():
    if len(sys.argv) < 2:
        sys.exit(1)
    dir_path = sys.argv[1]

    invoices_msgs = load_messages(os.path.join(dir_path, 'invoices.txt'))
    purchase_orders_msgs = load_messages(os.path.join(dir_path, 'purchase_orders.txt'))
    receipts_msgs = load_messages(os.path.join(dir_path, 'receipts.txt'))
    warehouse_scans_msgs = load_messages(os.path.join(dir_path, 'warehouse_scans.txt'))
    payments_msgs = load_messages(os.path.join(dir_path, 'payments.txt'))

    # Gather all PO IDs across all files in the directory
    all_pos = set()
    for fname in os.listdir(dir_path):
        if fname.endswith('.txt'):
            with open(os.path.join(dir_path, fname), 'r', encoding='utf-8') as f:
                all_pos.update(re.findall(r'\bPO-\d+\b', f.read()))
    sorted_pos = sorted(list(all_pos))

    def get_values(msgs, po, extract_fn):
        vals = set()
        for msg_po, body in msgs:
            if msg_po == po:
                v = extract_fn(body)
                if v is not None:
                    vals.add(v)
        return vals

    def resolve(po, primary_doc, primary_msgs, primary_fn, fallback_doc=None, fallback_msgs=None, fallback_fn=None):
        vals = get_values(primary_msgs, po, primary_fn)
        if len(vals) > 1:
            return "CONFLICT"
        elif len(vals) == 1:
            return [list(vals)[0], primary_doc]

        if fallback_doc and fallback_msgs is not None and fallback_fn is not None:
            fb_vals = get_values(fallback_msgs, po, fallback_fn)
            if len(fb_vals) > 1:
                return "CONFLICT"
            elif len(fb_vals) == 1:
                return [list(fb_vals)[0], fallback_doc]

        return "ABSENT"

    output = {}

    # pa.three_way_match
    for po in sorted_pos:
        pair_id = f"pa.three_way_match::{po}"
        output[pair_id] = {
            "invoice amount": resolve(po, "invoices", invoices_msgs, extract_invoice_amount),
            "order amount": resolve(po, "purchase_orders", purchase_orders_msgs, extract_po_amount),
            "quantity received": resolve(po, "receipts", receipts_msgs, extract_receipt_quantity),
            "quantity invoiced": resolve(po, "invoices", invoices_msgs, extract_invoice_quantity),
        }

    # pa.paid_in_window
    for po in sorted_pos:
        pair_id = f"pa.paid_in_window::{po}"
        output[pair_id] = {
            "goods received": resolve(po, "receipts", receipts_msgs, extract_receipt_date,
                                     "warehouse_scans", warehouse_scans_msgs, extract_warehouse_scan_date),
            "payment date": resolve(po, "payments", payments_msgs, extract_payment_date),
            "payment due": resolve(po, "invoices", invoices_msgs, extract_payment_due),
        }

    print(json.dumps(output, indent=2))

if __name__ == '__main__':
    main()
