import sys
import os
import json
import re
from decimal import Decimal
from datetime import date, timedelta


def parse_date(val):
    val = val.strip()
    m = re.match(r"^(\d{4})-W(\d{2})-([1-7])$", val)
    if m:
        y, w, d = int(m.group(1)), int(m.group(2)), int(m.group(3))
        # ISO week date to calendar date
        jan4 = date(y, 1, 4)
        start_week1 = jan4 - timedelta(days=jan4.isoweekday() - 1)
        res_date = start_week1 + timedelta(weeks=w - 1, days=d - 1)
        return res_date.strftime("%Y-%m-%d")
    if re.match(r"^\d{4}-\d{2}-\d{2}$", val):
        return val
    return val


def parse_crosstab_tsv(filepath):
    if not os.path.exists(filepath):
        return []
    with open(filepath, "r", encoding="utf-8") as f:
        lines = [line.rstrip("\r\n") for line in f if line.strip() and not line.startswith("#")]

    if not lines:
        return []

    header = lines[0].split("\t")
    num_records = len(header) - 1
    records = [{} for _ in range(num_records)]

    for line in lines[1:]:
        parts = line.split("\t")
        attr = parts[0].strip()
        for i in range(num_records):
            val = parts[i + 1].strip() if i + 1 < len(parts) else ""
            if val and val != "~":
                records[i][attr] = val
    return records


def evaluate_fact(entity_id, primary_doc, primary_attr, is_date, fallback_doc, fallback_attr, docs):
    # Check primary document
    recs = [r for r in docs.get(primary_doc, []) if r.get("order.key") == entity_id]
    vals = [r[primary_attr] for r in recs if primary_attr in r and r[primary_attr] not in ("", "~")]

    if vals:
        if is_date:
            parsed = [parse_date(v) for v in vals]
            if len(set(parsed)) > 1:
                return "CONFLICT"
            return [parsed[0], primary_doc]
        else:
            parsed = []
            for v in vals:
                try:
                    parsed.append((Decimal(v), v))
                except Exception:
                    parsed.append((v, v))
            if len(set(p[0] for p in parsed)) > 1:
                return "CONFLICT"
            return [parsed[0][1], primary_doc]

    # If primary document has no value, check fallback document
    if fallback_doc:
        recs_fb = [r for r in docs.get(fallback_doc, []) if r.get("order.key") == entity_id]
        vals_fb = [r[fallback_attr] for r in recs_fb if fallback_attr in r and r[fallback_attr] not in ("", "~")]
        if vals_fb:
            if is_date:
                parsed = [parse_date(v) for v in vals_fb]
                if len(set(parsed)) > 1:
                    return "CONFLICT"
                return [parsed[0], fallback_doc]
            else:
                parsed = []
                for v in vals_fb:
                    try:
                        parsed.append((Decimal(v), v))
                    except Exception:
                        parsed.append((v, v))
                if len(set(p[0] for p in parsed)) > 1:
                    return "CONFLICT"
                return [parsed[0][1], fallback_doc]

    return "ABSENT"


def main():
    if len(sys.argv) < 2:
        sys.exit(1)
    dir_path = sys.argv[1]

    doc_files = {
        "invoices": "invoices.tsv",
        "payments": "payments.tsv",
        "purchase_orders": "purchase_orders.tsv",
        "receipts": "receipts.tsv",
        "warehouse_scans": "warehouse_scans.tsv",
        "requisitions": "requisitions.tsv",
    }

    docs = {}
    for doc_name, fname in doc_files.items():
        fpath = os.path.join(dir_path, fname)
        docs[doc_name] = parse_crosstab_tsv(fpath)

    # Discover all order keys across all documents
    all_keys = set()
    for records in docs.values():
        for r in records:
            if "order.key" in r and r["order.key"]:
                all_keys.add(r["order.key"])
    entities = sorted(all_keys)

    rules = [
        (
            "pa.three_way_match",
            [
                ("invoice amount", "invoices", "bill.value.usd", False, None, None),
                ("order amount", "purchase_orders", "order.commit.usd", False, None, None),
                ("quantity received", "receipts", "goodsin.units", False, None, None),
                ("quantity invoiced", "invoices", "bill.qty.units", False, None, None),
            ],
        ),
        (
            "pa.paid_in_window",
            [
                ("goods received", "receipts", "goodsin.day.wk", True, "warehouse_scans", "scanner.hit.wk"),
                ("payment date", "payments", "funds.out.wk", True, None, None),
                ("payment due", "invoices", "bill.deadline.wk", True, None, None),
            ],
        ),
    ]

    output = {}
    for rule_name, fact_specs in rules:
        for entity in entities:
            pair_id = f"{rule_name}::{entity}"
            pair_facts = {}
            for fact_name, p_doc, p_attr, is_dt, fb_doc, fb_attr in fact_specs:
                pair_facts[fact_name] = evaluate_fact(entity, p_doc, p_attr, is_dt, fb_doc, fb_attr, docs)
            output[pair_id] = pair_facts

    print(json.dumps(output, indent=2))


if __name__ == "__main__":
    main()
