import os
import sys
import json
from decimal import Decimal


def parse_file(filepath):
    rows = []
    headers = None
    with open(filepath, "r", encoding="utf-8") as f:
        for line in f:
            line = line.rstrip("\r\n")
            if not line or line.startswith("#"):
                continue
            parts = [p.strip() for p in line.split("|")]
            if headers is None:
                headers = parts
            else:
                rows.append(dict(zip(headers, parts)))
    return rows


def format_date(val):
    val = val.strip()
    if not val:
        return None
    parts = val.split("/")
    if len(parts) == 3:
        m, d, y = parts
        return f"{int(y):04d}-{int(m):02d}-{int(d):02d}"
    return val


def format_amount(val):
    val = val.strip()
    if not val:
        return None
    return val


def amounts_agree(v1, v2):
    try:
        return Decimal(v1) == Decimal(v2)
    except Exception:
        return v1 == v2


def resolve_fact(entity, sources, datasets):
    for doc_name, col_name, val_type in sources:
        rows = datasets.get(doc_name, [])
        vals = []
        for r in rows:
            if r.get("PURCHASE_DOCUMENT_KEY") == entity:
                raw_val = r.get(col_name, "").strip()
                if raw_val:
                    if val_type == "date":
                        parsed = format_date(raw_val)
                    else:
                        parsed = format_amount(raw_val)
                    if parsed is not None:
                        vals.append(parsed)

        if not vals:
            continue

        # Check for conflict
        if val_type == "date":
            all_agree = all(v == vals[0] for v in vals)
        else:
            all_agree = all(amounts_agree(v, vals[0]) for v in vals)

        if all_agree:
            return [vals[0], doc_name]
        else:
            return "CONFLICT"

    return "ABSENT"


def main():
    if len(sys.argv) < 2:
        sys.exit(1)

    dir_path = sys.argv[1]

    doc_files = {
        "invoices": "invoices.txt",
        "payments": "payments.txt",
        "purchase_orders": "purchase_orders.txt",
        "receipts": "receipts.txt",
        "requisitions": "requisitions.txt",
        "warehouse_scans": "warehouse_scans.txt",
    }

    datasets = {}
    all_keys = set()

    for doc_name, filename in doc_files.items():
        filepath = os.path.join(dir_path, filename)
        if not os.path.exists(filepath):
            filepath = os.path.join(dir_path, doc_name)
        if os.path.exists(filepath):
            rows = parse_file(filepath)
            datasets[doc_name] = rows
            for r in rows:
                k = r.get("PURCHASE_DOCUMENT_KEY")
                if k:
                    all_keys.add(k)
        else:
            datasets[doc_name] = []

    sorted_keys = sorted(all_keys)

    rules = {
        "pa.three_way_match": [
            ("invoice amount", [("invoices", "VENDOR_BILLED_TOTAL", "amount")]),
            ("order amount", [("purchase_orders", "ORDER_NET_VALUE", "amount")]),
            ("quantity received", [("receipts", "GR_ACCEPTED_UNITS", "amount")]),
            ("quantity invoiced", [("invoices", "BILLED_UNIT_COUNT", "amount")]),
        ],
        "pa.paid_in_window": [
            (
                "goods received",
                [
                    ("receipts", "GR_POSTING_DAY", "date"),
                    ("warehouse_scans", "INBOUND_DOOR_EVENT_DAY", "date"),
                ],
            ),
            ("payment date", [("payments", "DISBURSEMENT_CLEARED_DAY", "date")]),
            ("payment due", [("invoices", "NET_DUE_DAY", "date")]),
        ],
    }

    output = {}

    for rule_id, fact_defs in rules.items():
        for entity in sorted_keys:
            pair_id = f"{rule_id}::{entity}"
            pair_result = {}
            for fact_name, sources in fact_defs:
                pair_result[fact_name] = resolve_fact(entity, sources, datasets)
            output[pair_id] = pair_result

    print(json.dumps(output, indent=2))


if __name__ == "__main__":
    main()
