                if len(set(dec_values)) > 1:
                    return "CONFLICT"
                return [values[0], doc_name]
            except Exception:
                if len(set(values)) > 1:
                    return "CONFLICT"
                return [values[0], doc_name]

    return "ABSENT"


def main():
    if len(sys.argv) < 2:
        sys.exit(1)

    directory = sys.argv[1]
    doc_names = ["invoices", "payments", "purchase_orders", "receipts", "warehouse_scans"]

    doc_by_po = {}
    all_pos = set()

    for name in doc_names:
        fpath = get_file_path(directory, name)
        rows = read_table(fpath)
        doc_by_po[name] = {}
        for r in rows:
            po = r.get("PURCHASE_DOCUMENT_KEY")
            if po:
                doc_by_po[name].setdefault(po, []).append(r)
                all_pos.add(po)

    given_entities = {p.split("::")[1] for p in GIVEN_PAIRS}
    if all_pos and all_pos != given_entities:
        pairs = []
        for rule_name in ["pa.three_way_match", "pa.paid_in_window"]:
            for po in sorted(all_pos):
                pairs.append(f"{rule_name}::{po}")
    else:
        pairs = GIVEN_PAIRS

    result = {}
    for pair_id in pairs:
        rule_name, entity = pair_id.split("::")
        facts_spec = RULES.get(rule_name, [])
        pair_result = {}
        for fact_name, sources, fact_type in facts_spec:
            pair_result[fact_name] = evaluate_fact(entity, sources, fact_type, doc_by_po)
        result[pair_id] = pair_result

    print(json.dumps(result, indent=2))


if __name__ == "__main__":
    main()
