import sys
import os
import re
import json

MONTHS = {
    'jan': 1, 'feb': 2, 'mar': 3, 'apr': 4, 'may': 5, 'jun': 6,
    'jul': 7, 'aug': 8, 'sep': 9, 'oct': 10, 'nov': 11, 'dec': 12
}

def parse_date(text):
    if not text:
        return None
    m = re.search(r'\b(\d{4})-(\d{2})-(\d{2})\b', text)
    if m:
        return f"{m.group(1)}-{m.group(2)}-{m.group(3)}"
    m = re.search(r'([A-Za-z]+)\.?\s+(\d{1,2}),\s+(\d{4})', text)
    if m:
        mon_str, day_str, year_str = m.group(1), m.group(2), m.group(3)
        mon_key = mon_str.lower()[:3]
        if mon_key in MONTHS:
            return f"{int(year_str):04d}-{MONTHS[mon_key]:02d}-{int(day_str):02d}"
    m = re.search(r'(\d{1,2})\s+([A-Za-z]+)\.?\s+(\d{4})', text)
    if m:
        day_str, mon_str, year_str = m.group(1), m.group(2), m.group(3)
        mon_key = mon_str.lower()[:3]
        if mon_key in MONTHS:
            return f"{int(year_str):04d}-{MONTHS[mon_key]:02d}-{int(day_str):02d}"
    return None

def parse_amount(text):
    if not text:
        return None
    m = re.search(r'[\d,]+(?:\.\d+)?', text)
    if not m:
        return None
    return m.group(0).replace(',', '')

def read_file(dir_path, doc_name):
    for fname in [f"{doc_name}.html", doc_name]:
        full_path = os.path.join(dir_path, fname)
        if os.path.exists(full_path):
            with open(full_path, 'r', encoding='utf-8') as f:
                return f.read()
    return ""

def parse_sheets(html_content):
    sheets = []
    articles = re.findall(r'<article[^>]*class=["\'][^"\']*sheet[^"\']*["\'][^>]*>(.*?)</article>', html_content, re.DOTALL | re.IGNORECASE)
    if not articles:
        articles = [html_content]
    for art in articles:
        sheet = {}
        rows = re.findall(r'<tr[^>]*>\s*<th[^>]*>(.*?)</th>\s*<td([^>]*)>(.*?)</td>\s*</tr>', art, re.DOTALL | re.IGNORECASE)
        for th_raw, td_attr, td_raw in rows:
            th = re.sub(r'<[^>]+>', '', th_raw).strip().lower()
            if 'void' in td_attr.lower() or 'left blank' in td_raw.lower():
                continue
            val = re.sub(r'<[^>]+>', '', td_raw).strip()
            if not val or val in ('—', '&mdash;'):
                continue
            sheet[th] = val
        if sheet:
            sheets.append(sheet)
    return sheets

def get_entity_id(sheet):
    for k, v in sheet.items():
        if 'procurement' in k or 'reference' in k:
            m = re.search(r'PO-\d+', v)
            if m:
                return m.group(0)
            return v.strip()
    return None

def find_field_value(sheet, field_patterns):
    for k, v in sheet.items():
        for pat in field_patterns:
            if pat in k:
                return v
    return None

def extract_values(sheets, entity_id, field_patterns, val_type):
    vals = []
    for sheet in sheets:
        if get_entity_id(sheet) == entity_id:
            raw_val = find_field_value(sheet, field_patterns)
            if raw_val is not None:
                parsed = parse_amount(raw_val) if val_type == 'amount' else parse_date(raw_val)
                if parsed is not None:
                    vals.append(parsed)
    return vals

def resolve_fact(docs_sheets, entity_id, primary_doc, primary_patterns, val_type, fallback_doc=None, fallback_patterns=None):
    primary_vals = extract_values(docs_sheets.get(primary_doc, []), entity_id, primary_patterns, val_type)
    if primary_vals:
        if len(set(primary_vals)) > 1:
            return "CONFLICT"
        return [primary_vals[0], primary_doc]

    if fallback_doc:
        fallback_vals = extract_values(docs_sheets.get(fallback_doc, []), entity_id, fallback_patterns, val_type)
        if fallback_vals:
            if len(set(fallback_vals)) > 1:
                return "CONFLICT"
            return [fallback_vals[0], fallback_doc]

    return "ABSENT"

def main():
    if len(sys.argv) < 2:
        sys.exit(1)
    dir_path = sys.argv[1]

    doc_names = ['invoices', 'purchase_orders', 'receipts', 'warehouse_scans', 'payments', 'requisitions']
    docs_sheets = {}
    all_entity_ids = set()

    for doc in doc_names:
        content = read_file(dir_path, doc)
        if content:
            sheets = parse_sheets(content)
            docs_sheets[doc] = sheets
            for sheet in sheets:
                eid = get_entity_id(sheet)
                if eid:
                    all_entity_ids.add(eid)

    entity_ids = sorted(list(all_entity_ids))

    rules = [
        ('pa.three_way_match', [
            ('invoice amount', 'invoices', ['invoice grand total', 'invoice amount', 'grand total', 'invoice total'], 'amount', None, None),
            ('order amount', 'purchase_orders', ['total order value', 'order amount', 'total order', 'order value'], 'amount', None, None),
            ('quantity received', 'receipts', ['units counted on delivery', 'units counted', 'quantity received', 'units received'], 'amount', None, None),
            ('quantity invoiced', 'invoices', ['units charged', 'quantity invoiced', 'units invoiced'], 'amount', None, None),
        ]),
        ('pa.paid_in_window', [
            ('goods received', 'receipts', ['delivery booked', 'delivery date', 'date goods were received', 'goods received'], 'date',
             'warehouse_scans', ['dock scanner stamp', 'scanner stamp', 'dock scan', 'scan date', 'warehouse scan']),
            ('payment date', 'payments', ['funds released', 'payment date', 'disbursement date'], 'date', None, None),
            ('payment due', 'invoices', ['payment deadline', 'payment due date', 'payment due', 'due date'], 'date', None, None),
        ])
    ]

    result = {}
    for rule_name, facts in rules:
        for eid in entity_ids:
            pair_id = f"{rule_name}::{eid}"
            fact_map = {}
            for fact_name, prim_doc, prim_pats, vtype, fb_doc, fb_pats in facts:
                fact_map[fact_name] = resolve_fact(docs_sheets, eid, prim_doc, prim_pats, vtype, fb_doc, fb_pats)
            result[pair_id] = fact_map

    print(json.dumps(result, indent=2))

if __name__ == '__main__':
    main()
