import html
import json
import os
import re
import sys

MONTH_MAP = {
    'jan': 1, 'january': 1,
    'feb': 2, 'february': 2,
    'mar': 3, 'march': 3,
    'apr': 4, 'april': 4,
    'may': 5,
    'jun': 6, 'june': 6,
    'jul': 7, 'july': 7,
    'aug': 8, 'august': 8,
    'sep': 9, 'sept': 9, 'september': 9,
    'oct': 10, 'october': 10,
    'nov': 11, 'november': 11,
    'dec': 12, 'december': 12,
}

RULES = {
    'pa.three_way_match': [
        ('invoice amount', [('invoices', 'Invoice grand total', 'amount')]),
        ('order amount', [('purchase_orders', 'Total order value', 'amount')]),
        ('quantity received', [('receipts', 'Units counted on delivery', 'amount')]),
        ('quantity invoiced', [('invoices', 'Units charged', 'amount')]),
    ],
    'pa.paid_in_window': [
        ('goods received', [
            ('receipts', 'Delivery booked', 'date'),
            ('warehouse_scans', 'Dock scanner stamp', 'date'),
        ]),
        ('payment date', [('payments', 'Funds released', 'date')]),
        ('payment due', [('invoices', 'Payment deadline', 'date')]),
    ],
}


def parse_amount(val_str):
    if not val_str:
        return None
    m = re.search(r'[-+]?[0-9,]*\.?[0-9]+', val_str)
    if m:
        return m.group(0).replace(',', '')
    return None


def parse_date(val_str):
    if not val_str:
        return None
    m_iso = re.search(r'\b(\d{4})-(\d{2})-(\d{2})\b', val_str)
    if m_iso:
        return f"{m_iso.group(1)}-{m_iso.group(2)}-{m_iso.group(3)}"

    m = re.search(r'\b([A-Za-z]+)\.?\s+(\d{1,2}),?\s+(\d{4})\b', val_str)
    if m:
        month_str = m.group(1).lower()
        if month_str in MONTH_MAP:
            return f"{int(m.group(3)):04d}-{MONTH_MAP[month_str]:02d}-{int(m.group(2)):02d}"

    m_dmy = re.search(r'\b(\d{1,2})\s+([A-Za-z]+)\.?\s+(\d{4})\b', val_str)
    if m_dmy:
        month_str = m_dmy.group(2).lower()
        if month_str in MONTH_MAP:
            return f"{int(m_dmy.group(3)):04d}-{MONTH_MAP[month_str]:02d}-{int(m_dmy.group(1)):02d}"

    return None


def parse_value(val_str, val_type):
    if val_type == 'amount':
        return parse_amount(val_str)
    elif val_type == 'date':
        return parse_date(val_str)
    return val_str


def parse_html_sheets(content):
    sheets = []
    articles = re.findall(r'<article\b[^>]*>(.*?)</article>', content, flags=re.DOTALL | re.IGNORECASE)
    for art in articles:
        rows = re.findall(r'<tr[^>]*>\s*<th[^>]*>(.*?)</th>\s*<td([^>]*)>(.*?)</td>\s*</tr>', art, flags=re.DOTALL | re.IGNORECASE)
        sheet_data = {}
        for th, td_attrs, td in rows:
            th_clean = html.unescape(re.sub(r'<[^>]+>', '', th)).strip()
            if 'void' in td_attrs:
                continue
            td_clean = html.unescape(re.sub(r'<[^>]+>', '', td)).strip()
            if not td_clean or 'left blank' in td_clean.lower() or td_clean in ('—', '-'):
                continue
            sheet_data[th_clean] = td_clean
        if sheet_data:
            sheets.append(sheet_data)
    return sheets


def main():
    if len(sys.argv) < 2:
        sys.exit(1)

    dir_path = sys.argv[1]
    doc_names = ['invoices', 'payments', 'purchase_orders', 'receipts', 'requisitions', 'warehouse_scans']
    doc_records = {}

    for doc_name in doc_names:
        file_path = os.path.join(dir_path, f"{doc_name}.html")
        if not os.path.isfile(file_path):
            file_path = os.path.join(dir_path, doc_name)
        if os.path.isfile(file_path):
            with open(file_path, 'r', encoding='utf-8') as f:
                content = f.read()
            doc_records[doc_name] = parse_html_sheets(content)
        else:
            doc_records[doc_name] = []

    all_entities = set()
    for sheets in doc_records.values():
        for sheet in sheets:
            ref = sheet.get('Procurement reference')
            if ref:
                all_entities.add(ref)

    sorted_entities = sorted(all_entities)

    output = {}

    for rule_name, fact_specs in RULES.items():
        for entity in sorted_entities:
            pair_id = f"{rule_name}::{entity}"
            pair_result = {}

            for fact_name, doc_options in fact_specs:
                fact_resolved = False
                for doc_name, field_name, val_type in doc_options:
                    sheets = doc_records.get(doc_name, [])
                    values = []
                    for sheet in sheets:
                        if sheet.get('Procurement reference') == entity:
                            raw_val = sheet.get(field_name)
                            if raw_val is not None:
                                parsed = parse_value(raw_val, val_type)
                                if parsed is not None:
                                    values.append(parsed)

                    if values:
                        fact_resolved = True
                        unique_values = set(values)
                        if len(unique_values) == 1:
                            pair_result[fact_name] = [values[0], doc_name]
                        else:
                            pair_result[fact_name] = "CONFLICT"
                        break

                if not fact_resolved:
                    pair_result[fact_name] = "ABSENT"

            output[pair_id] = pair_result

    print(json.dumps(output, indent=2))


if __name__ == '__main__':
    main()
