import sys
import os
import json
import sqlite3
import datetime
from decimal import Decimal

def format_date(epd):
    d = datetime.date(1970, 1, 1) + datetime.timedelta(days=int(epd))
    return d.isoformat()

def format_amount(val, divisor=1):
    if divisor == 100:
        if val % 100 == 0:
            return str(val // 100)
        else:
            d = Decimal(val) / Decimal(100)
            return format(d, 'f')
    elif divisor == 1:
        return str(val)
    else:
        d = Decimal(val) / Decimal(divisor)
        s = format(d, 'f')
        if '.' in s:
            s = s.rstrip('0').rstrip('.')
        return s

def load_tables(dir_path):
    doc_tables = {}
    doc_files = {
        'invoices': 'invoices.sql',
        'payments': 'payments.sql',
        'purchase_orders': 'purchase_orders.sql',
        'receipts': 'receipts.sql',
        'warehouse_scans': 'warehouse_scans.sql',
        'requisitions': 'requisitions.sql'
    }

    for doc_name, fname in doc_files.items():
        fpath = os.path.join(dir_path, fname)
        if not os.path.exists(fpath):
            continue
        conn = sqlite3.connect(':memory:')
        with open(fpath, 'r', encoding='utf-8') as f:
            conn.executescript(f.read())

        cursor = conn.cursor()
        cursor.execute("SELECT name FROM sqlite_master WHERE type='table' AND name != 'sqlite_sequence';")
        tables = [row[0] for row in cursor.fetchall()]
        if tables:
            tbl_name = tables[0]
            cursor.execute(f"PRAGMA table_info({tbl_name});")
            cols = [col[1] for col in cursor.fetchall()]
            doc_tables[doc_name] = {
                'conn': conn,
                'table': tbl_name,
                'cols': cols
            }

    return doc_tables

def get_fact_value(doc_tables, ord_code, primary_spec, fallback_spec=None, fmt='amount', divisor=1):
    # primary_spec: (doc_name, col_name)
    specs = [primary_spec]
    if fallback_spec:
        specs.append(fallback_spec)

    for doc_name, col_name in specs:
        if doc_name not in doc_tables:
            continue
        info = doc_tables[doc_name]
        conn = info['conn']
        tbl = info['table']
        if col_name not in info['cols']:
            continue

        cursor = conn.cursor()
        cursor.execute(f"SELECT {col_name} FROM {tbl} WHERE ord_code = ?", (ord_code,))
        rows = cursor.fetchall()

        non_null_vals = [r[0] for r in rows if r[0] is not None]
        if not non_null_vals:
            # no value in this document for this entity, try next if fallback
            continue

        distinct_vals = list(set(non_null_vals))
        if len(distinct_vals) > 1:
            return "CONFLICT"

        val = distinct_vals[0]
        if fmt == 'date':
            formatted_val = format_date(val)
        else:
            formatted_val = format_amount(val, divisor=divisor)

        return [formatted_val, doc_name]

    return "ABSENT"

def main():
    if len(sys.argv) < 2:
        sys.exit(1)

    dir_path = sys.argv[1]
    doc_tables = load_tables(dir_path)

    # Collect all unique ord_code
    all_ord_codes = set()
    for doc_name, info in doc_tables.items():
        if 'ord_code' in info['cols']:
            conn = info['conn']
            tbl = info['table']
            cursor = conn.cursor()
            cursor.execute(f"SELECT DISTINCT ord_code FROM {tbl}")
            for r in cursor.fetchall():
                if r[0]:
                    all_ord_codes.add(r[0])

    sorted_ord_codes = sorted(list(all_ord_codes))

    result = {}

    # Rule 1: pa.three_way_match
    for ord_code in sorted_ord_codes:
        pair_id = f"pa.three_way_match::{ord_code}"
        facts = {}
        facts["invoice amount"] = get_fact_value(
            doc_tables, ord_code, ('invoices', 'billed_cents'), fmt='amount', divisor=100
        )
        facts["order amount"] = get_fact_value(
            doc_tables, ord_code, ('purchase_orders', 'commit_cents'), fmt='amount', divisor=100
        )
        facts["quantity received"] = get_fact_value(
            doc_tables, ord_code, ('receipts', 'dock_unit_ct'), fmt='amount', divisor=1
        )
        facts["quantity invoiced"] = get_fact_value(
            doc_tables, ord_code, ('invoices', 'billed_unit_ct'), fmt='amount', divisor=1
        )
        result[pair_id] = facts

    # Rule 2: pa.paid_in_window
    for ord_code in sorted_ord_codes:
        pair_id = f"pa.paid_in_window::{ord_code}"
        facts = {}
        facts["goods received"] = get_fact_value(
            doc_tables, ord_code,
            ('receipts', 'goods_in_epd'),
            fallback_spec=('warehouse_scans', 'scanner_hit_epd'),
            fmt='date'
        )
        facts["payment date"] = get_fact_value(
            doc_tables, ord_code, ('payments', 'funds_out_epd'), fmt='date'
        )
        facts["payment due"] = get_fact_value(
            doc_tables, ord_code, ('invoices', 'pay_deadline_epd'), fmt='date'
        )
        result[pair_id] = facts

    print(json.dumps(result, indent=2))

if __name__ == '__main__':
    main()
